package com.networkmonitorpro.ui.viewmodel; import android.app.*; import androidx.annotation.NonNull; import androidx.lifecycle.*; import com.networkmonitorpro.data.repository.*; import com.networkmonitorpro.network.*; public class MainViewModel extends AndroidViewModel{ public final NetworkDetector detector; public final NotificationRepository notifications; public final DownloadRepository downloads; public final AnalyticsRepository analytics; public MainViewModel(@NonNull Application a){super(a); detector=new NetworkDetector(a); notifications=new NotificationRepository(a); downloads=new DownloadRepository(a); analytics=new AnalyticsRepository(a); detector.snapshots.observeForever(analytics::record); detector.start();} protected void onCleared(){detector.stop();} }
